{"success": true, "data": {"stdout": """"Compute bootstrap confidence intervals for SciERC and DocRED experiments."""

import json
import numpy as np
from pathlib import Path

# --- SciERC normalization (from violation_checker.py) ---

SCIERC_TYPE_MAP = {
    "otherscientificterm": "OtherScientificTerm",
    "other-scientificterm": "OtherScientificTerm",
    "other_scientific_term": "OtherScientificTerm",
    "scientificterm": "OtherScientificTerm",
    "other": "OtherScientificTerm",
}

def scierc_normalize_type(t, valid_types):
    t_lower = t.strip().lower().replace(" ", "").replace("_", "").replace("-", "")
    for vt in valid_types:
        if t_lower == vt.lower().replace(" ", "").replace("_", "").replace("-", ""):
            return vt
    if t_lower in SCIERC_TYPE_MAP:
        return SCIERC_TYPE_MAP[t_lower]
    return None

# --- DocRED normalization (from violation_checker_docred.py) ---

DOCRED_VALID_ENTITY_TYPES = {"PER", "ORG", "LOC", "TIME", "NUM", "MISC"}

DOCRED_ENTITY_TYPE_ALIASES = {
    'PERSON': 'PER', 'PEOPLE': 'PER',
    'ORGANIZATION': 'ORG', 'ORGANISATION': 'ORG',
    'LOCATION': 'LOC',
    'NUMBER': 'NUM', 'NUMERICAL': 'NUM',
    'MISCELLANEOUS': 'MISC',
}

def docred_normalize_entity_type(raw_type):
    t = raw_type.strip().upper()
    return DOCRED_ENTITY_TYPE_ALIASES.get(t, t)

def _levenshtein(s1, s2):
    if len(s1) < len(s2):
        return _levenshtein(s2, s1)
    if len(s2) == 0:
        return len(s1)
    prev_row = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1):
        curr_row = [i + 1]
        for j, c2 in enumerate(s2):
            curr_row.append(min(prev_row[j + 1] + 1, curr_row[j] + 1, prev_row[j] + (c1 != c2)))
        prev_row = curr_row
    return prev_row[-1]

def build_name_to_id(rel_types):
    name_to_id = {}
    for rid, rname in rel_types.items():
        name_to_id[rname.lower().strip()] = rid
        name_to_id[rid.lower()] = rid
    return name_to_id

def docred_normalize_relation(rel_name, rel_types, name_to_id):
    rel_key = name_to_id.get(rel_name.lower().strip())
    if rel_key:
        return rel_key
    rel_tokens = set(rel_name.strip().lower().split())
    best_pid, best_overlap = None, 0.0
    for rid, rname in rel_types.items():
        rname_tokens = set(rname.lower().split())
        if rel_tokens and rname_tokens:
            ratio = len(rel_tokens & rname_tokens) / len(rel_tokens | rname_tokens)
            if ratio > 0.8 and ratio > best_overlap:
                best_overlap = ratio
                best_pid = rid
    if best_pid:
        return best_pid
    for rid, rname in rel_types.items():
        if _levenshtein(rel_name.strip().lower(), rname.lower()) <= 2:
            return rid
    return None

# --- Per-sample stats ---

def scierc_sample_stats(rec, valid_entity_types):
    parsed = rec.get("parsed_output")
    gold_ents = rec.get("gold_entities", [])
    gold_rels = rec.get("gold_relations", [])

    gold_ent_set = set((e["text"].lower().strip(), e["type"]) for e in gold_ents)
    gold_rel_set = set((r["head"].lower().strip(), r["tail"].lower().strip(), r["type"]) for r in gold_rels)

    if parsed is None:
        return {"ent_tp": 0, "ent_gold": len(gold_ent_set), "ent_pred": 0,
                "rel_tp": 0, "rel_gold": len(gold_rel_set), "rel_pred": 0}

    entities = parsed.get("entities", [])
    relations = parsed.get("relations", [])

    pred_ent_set = set()
    for e in entities:
        nt = scierc_normalize_type(e.get("type", ""), valid_entity_types)
        if nt:
            pred_ent_set.add((e.get("text", "").lower().strip(), nt))

    pred_rel_set = set((r.get("head", "").lower().strip(), r.get("tail", "").lower().strip(), r.get("type", "")) for r in relations)

    return {
        "ent_tp": len(gold_ent_set & pred_ent_set), "ent_gold": len(gold_ent_set), "ent_pred": len(pred_ent_set),
        "rel_tp": len(gold_rel_set & pred_rel_set), "rel_gold": len(gold_rel_set), "rel_pred": len(pred_rel_set),
    }

def docred_sample_stats(rec, rel_types, name_to_id):
    parsed = rec.get("parsed_output")
    gold_ents = rec.get("gold_entities", [])
    gold_rels = rec.get("gold_relations", [])

    gold_ent_set = set((e["text"].lower().strip(), e["type"]) for e in gold_ents)
    gold_rel_set = set((r["head"].lower().strip(), r["tail"].lower().strip(), r["type"]) for r in gold_rels)

    if parsed is None:
        return {"ent_tp": 0, "ent_gold": 0, "ent_pred": 0,
                "rel_tp": 0, "rel_gold": 0, "rel_pred": 0}

    entities = parsed.get("entities", [])
    relations = parsed.get("relations", [])

    pred_ent_set = set((e.get("text", "").lower().strip(), e.get("type", "")) for e in entities)

    pred_rel_set = set()
    for r in relations:
        pid = docred_normalize_relation(r.get("type", ""), rel_types, name_to_id)
        if pid:
            pred_rel_set.add((r.get("head", "").lower().strip(), r.get("tail", "").lower().strip(), pid))
        else:
            pred_rel_set.add((r.get("head", "").lower().strip(), r.get("tail", "").lower().strip(), f"__OOV__{r.get('type', '')}"))

    return {
        "ent_tp": len(gold_ent_set & pred_ent_set), "ent_gold": len(gold_ent_set), "ent_pred": len(pred_ent_set),
        "rel_tp": len(gold_rel_set & pred_rel_set), "rel_gold": len(gold_rel_set), "rel_pred": len(pred_rel_set),
    }

# --- Bootstrap ---

def _f1_from_arrays(tp, gold, pred):
    p = np.where(pred > 0, tp / pred, 0.0)
    r = np.where(gold > 0, tp / gold, 0.0)
    denom = p + r
    return np.where(denom > 0, 2 * p * r / denom, 0.0)

def bootstrap_f1(sample_stats, n_bootstrap=10000, seed=42):
